const rows = $input.all().map(i => i.json || {});

function isTrue(v) {
  if (v === null || v === undefined) return false;
  const s = String(v).trim().toLowerCase();
  return s === 'true' || s === 'yes' || s === '1';
}

const unreported = rows.filter(r => {
  const created = isTrue(r['WI Created on EasyBOP']);
  const reported = isTrue(r['Upload Reported']);
  return created && !reported;
});

if (unreported.length === 0) {
  return [{ json: { has_unreported: false } }];
}

return [{
  json: {
    has_unreported: true,
    rows: unreported,
    count: unreported.length
  }
}];

const rows = $input.first().json.rows;

let tableRows = '';
for (const r of rows) {
  const corf = r['Client Order Reference'] || r['Client Order Ref'] || r['Client Order Ref.'] || 'Unknown';

  const addr1 = r['Address 1'] || '';
  const addr2 = r['Address 2'] || '';
  const addr3 = r['Address 3'] || '';
  const addr4 = r['Address 4'] || '';
  const parts = [addr1, addr2, addr3, addr4].filter(x => String(x).trim() !== '');

  let addr = parts.join(', ');
  if (!addr) {
     addr = r['Q1.1 Address'] || r['Address'] || r['Works Instruction Address'] || 'Unknown Address';
  }

  tableRows += `<tr><td style="padding: 10px; border-bottom: 1px solid #eee;">${corf}</td><td style="padding: 10px; border-bottom: 1px solid #eee;">${addr}</td></tr>`;
}

const logo = 'https://jeffway.co.uk/wp-content/uploads/2025/05/jeffway-group-1.svg';
const reportDate = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London' }).replace(',', '');

const html = [
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>',
  '<body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f4f4f4;">',
  '<table width="100%" style="background:#f4f4f4;padding:20px;"><tr><td align="center">',
  '<table width="640" style="background:#fff;border-radius:8px;border-spacing:0;overflow:hidden;">',
  '<tr><td style="background:#000;padding:20px;text-align:center;"><img src="' + logo + '" style="max-width:160px;" alt="Jeffway"></td></tr>',
  '<tr><td style="padding:24px;"><h2 style="margin:0;">Stage 1 — Work Instructions Uploaded</h2>',
  '<p style="color:#555;">Generated: <strong>' + reportDate + '</strong> (Europe/London)</p>',
  '<p style="color:#444;font-size:14px;"><strong>' + rows.length + '</strong> new work instructions were successfully created on EasyBOP during the last run.</p>',
  '<table style="width:100%; border-collapse:collapse; margin-top:20px; font-size:14px; text-align:left;">',
  '<thead><tr><th style="padding:10px; border-bottom:2px solid #ccc;">Client Order Ref</th><th style="padding:10px; border-bottom:2px solid #ccc;">Address</th></tr></thead>',
  '<tbody>' + tableRows + '</tbody></table>',
  '</td></tr>',
  '<tr><td style="background:#f9f9f9;padding:16px;text-align:center;font-size:12px;color:#777;">Jeffway Group · Automated Stage 1 Report</td></tr>',
  '</table></td></tr></table></body></html>'
].join('');

return [{
  json: {
    subject: `[Stage 1] Work Instructions Uploaded (${rows.length})`,
    html: html,
    rows_to_mark: rows
  }
}];

const rows = $('Prepare Report Email').first().json.rows_to_mark;
return rows.map(r => ({
  json: {
    'Client Order Reference': r['Client Order Reference'] || r['Client Order Ref'] || r['Client Order Ref.'],
    'Upload Reported': 'TRUE',
    'row_number': r.row_number || r.__rowNumber
  }
}));
